using System.Security.Claims;using System.Net.Http.Headers;using System.Text.Json;using EduForge.Domain;using EduForge.Infrastructure;
namespace EduForge.Api;
public record IllustrationInput(string Prompt);
public static class ImageGenerationEndpoints {
 public static void MapImageGeneration(this WebApplication app){app.MapPost("/api/ai/illustration",async(IllustrationInput input,ClaimsPrincipal user,IConfiguration config,IHttpClientFactory clients,MaterialDbContext db,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(input.Prompt)||input.Prompt.Length>2000)return Results.BadRequest(new{message="Описание иллюстрации: от 1 до 2000 символов."});var key=config["AI__ApiKey"]??config["AI:ApiKey"];var model=config["AI__ImageModel"]??config["AI:ImageModel"]??"gpt-image-2.5-sunburst";if(string.IsNullOrWhiteSpace(key))return Results.Problem("AI-ключ не настроен.",statusCode:503);using var http=clients.CreateClient();http.Timeout=TimeSpan.FromMinutes(3);using var request=new HttpRequestMessage(HttpMethod.Post,"https://api.openai.com/v1/images/generations");request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",key);request.Content=JsonContent.Create(new{model,prompt="Учебная иллюстрация для преподавателя. "+input.Prompt,size="1024x1024",quality="low",output_format="png",n=1});try{using var response=await http.SendAsync(request,ct);if(!response.IsSuccessStatusCode)return Results.Problem("Не удалось создать иллюстрацию. Проверьте доступ к модели изображений и баланс API.",statusCode:503);using var json=JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct));var encoded=json.RootElement.GetProperty("data")[0].GetProperty("b64_json").GetString()!;if(encoded.Length>14*1024*1024)return Results.Problem("Изображение слишком большое.",statusCode:503);var data=Convert.FromBase64String(encoded);if(data.Length<8||!data.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))return Results.Problem("Некорректный ответ AI.",statusCode:503);var asset=new MediaAsset{TeacherId=Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!),ContentType="image/png",Data=data};db.MediaAssets.Add(asset);await db.SaveChangesAsync(ct);return Results.Ok(new{url=$"/api/media/{asset.Id}"});}catch(HttpRequestException){return Results.Problem("AI-провайдер недоступен.",statusCode:503);}catch(TaskCanceledException)when(!ct.IsCancellationRequested){return Results.Problem("Время генерации истекло.",statusCode:504);}catch(Exception e)when(e is JsonException or FormatException or KeyNotFoundException or InvalidOperationException){return Results.Problem("Некорректный ответ генератора.",statusCode:503);}}).RequireAuthorization().RequireRateLimiting("ai");}
}
